onChange.script:
if previousValue is not None and currentValue.value != previousValue.value:
	project = currentValue.value
	self.custom.key = '' if project in ('', '*') else (self.custom.linkKey or 'report:overview')
	self.custom.linkKey = ''
	self.custom.selected = {}
	self.custom.history = []

transforms.code:
code = inspector.source.script(value.project, value.source, value.bi)
if not code:
	if value.source:
		return '_No script behind this finding - it is declared in the view (a binding, an action, an embed or a setting)._'
	return '_Select a row to see the script it was found in._'
return '```python\n' + code.replace('\t', '    ') + '\n```'

if not value.project:
	return '## Pick a project\n\nChoose a project on this gateway from the list at the top. The Inspector reads it live: pages, scripts, named queries and the gateway scripts that run with no page open.'
if value.mode == 'markdown' or value.key == 'report:overview':
	return inspector.source.markdown(value.project, value.key, value.follow, [k for k in value.show if value.show[k]])
return ''

config.script:
# A shared link: /<project>/<item>, both URL-decoded by the router.
if self.params.project:
	self.custom.linkKey = self.params.item or ''
	if self.custom.project == self.params.project:
		self.custom.key = self.params.item or 'report:overview'
		self.custom.linkKey = ''
	else:
		self.custom.project = self.params.project

pos = self.view.custom.leftPos
try:
	width = float(str(pos).replace('px', ''))
except ValueError:
	width = 300
if width > 24:
	self.view.custom.leftLast = pos
	self.view.custom.leftPos = 0
else:
	self.view.custom.leftPos = self.view.custom.leftLast or 300

if event.data:
	self.view.rootContainer.go(event.data)
else:
	# A folder: clicking its label opens or closes it, not only the chevron.
	node = self.props.items[event.itemPath[0]]
	for i in event.itemPath[1:]:
		node = node['items'][i]
	node['expanded'] = not node['expanded']

history = list(self.view.custom.history)
if history:
	self.view.custom.key = history.pop()
	self.view.custom.history = history
	self.view.custom.selected = {}

customMethods.script:
# Every move to another page or check goes through here, so Back can retrace it.
view = self.view
if key and key != view.custom.key:
	view.custom.history = (list(view.custom.history) + [view.custom.key])[-50:] if view.custom.key else list(view.custom.history)
	view.custom.key = key
	view.custom.selected = {}
